CREATE TABLE IF NOT EXISTS project_intelligence_passports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL UNIQUE REFERENCES projects(id) ON DELETE CASCADE, passport_version integer NOT NULL DEFAULT 1, passport_status text NOT NULL DEFAULT 'Draft', evidence_state text NOT NULL DEFAULT 'insufficient_data', readiness_state text NOT NULL DEFAULT 'not_ready', overall_readiness_score integer NOT NULL DEFAULT 0 CHECK (overall_readiness_score BETWEEN 0 AND 100), blocker_count integer NOT NULL DEFAULT 0, source_count integer NOT NULL DEFAULT 0, evidence_count integer NOT NULL DEFAULT 0, verified_evidence_count integer NOT NULL DEFAULT 0, summary text, generated_at timestamptz, generated_by text, supersedes_id uuid REFERENCES project_intelligence_passports(id) ON DELETE SET NULL, canonical_hash text, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());

CREATE TABLE IF NOT EXISTS project_readiness_gaps (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, domain text NOT NULL, requirement_code text NOT NULL, title text NOT NULL, description text, priority text NOT NULL DEFAULT 'medium', blocking boolean NOT NULL DEFAULT true, status text NOT NULL DEFAULT 'open', evidence_required text, evidence_reference uuid, owner_reference text, source_reference text, due_date date, resolution_notes text, resolved_at timestamptz, resolved_by text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,requirement_code));

CREATE TABLE IF NOT EXISTS project_pipeline_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, from_state text, to_state text NOT NULL, reason text, evidence_reference text, actor_reference text, occurred_at timestamptz NOT NULL DEFAULT now());

CREATE INDEX IF NOT EXISTS idx_project_readiness_gaps_project_status ON project_readiness_gaps(project_id,status,blocking);
CREATE INDEX IF NOT EXISTS idx_project_pipeline_events_project_time ON project_pipeline_events(project_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_project_intelligence_passports_state ON project_intelligence_passports(readiness_state,evidence_state);